import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:qr_flutter/qr_flutter.dart';
import 'package:pdf/widgets.dart' as pw;
import 'package:printing/printing.dart';
void main()=>runApp(const MaterialApp(debugShowCheckedModeBanner:false,home:Demo()));
class Demo extends StatefulWidget{const Demo({super.key});@override State<Demo> createState()=>_DemoState();}
class _DemoState extends State<Demo>{
int tab=0;
final assets=[{'id':'FRS-001','name':'CO2 Fire Extinguisher','site':'Sandton Reception'},{'id':'FRS-002','name':'Hose Reel','site':'Warehouse A'},{'id':'FRS-003','name':'Fire Hydrant','site':'Warehouse Exterior'},{'id':'FRS-004','name':'Smoke Detector','site':'Level 1'},{'id':'FRS-005','name':'Sprinkler','site':'Warehouse Ceiling'},{'id':'FRS-006','name':'Suppression Cylinder','site':'Server Room'}];
List<Map<String,dynamic>> inspections=[],defects=[];Map<String,String> answers={};bool signed=false;String technician='Demo Technician',notes='';
final questions=['Accessible and identifiable','Physical condition acceptable','Label and instructions legible','Mounted correctly','No damage or obstruction','Operational readiness'];
@override void initState(){super.initState();restore();}
Future<void> restore()async{final p=await SharedPreferences.getInstance();try{inspections=(jsonDecode(p.getString('inspections')??'[]') as List).map((e)=>Map<String,dynamic>.from(e)).toList();defects=(jsonDecode(p.getString('defects')??'[]') as List).map((e)=>Map<String,dynamic>.from(e)).toList();setState((){});}catch(_){}}
Future<void> save()async{final p=await SharedPreferences.getInstance();await p.setString('inspections',jsonEncode(inspections));await p.setString('defects',jsonEncode(defects));}
Future<void> pdf(Map<String,dynamic> r)async{final d=pw.Document();d.addPage(pw.MultiPage(build:(c)=>[pw.Text('FIRE RISK SYSTEMS',style:pw.TextStyle(fontSize:23,fontWeight:pw.FontWeight.bold)),pw.Text('DEMO SERVICE REPORT - SAMPLE ONLY'),pw.SizedBox(height:16),pw.Text('Asset: '+r['asset'].toString()),pw.Text('Site: '+r['site'].toString()),pw.Text('Technician: '+r['technician'].toString()),pw.Text('Date: '+r['date'].toString()),pw.Text('Result: '+r['result'].toString()),pw.SizedBox(height:16),...(r['answers'] as Map).entries.map((e)=>pw.Text(e.key.toString()+': '+e.value.toString())),pw.Text('Notes: '+r['notes'].toString())]));await Printing.sharePdf(bytes:await d.save(),filename:'FRS-demo-'+r['id'].toString()+'.pdf');}
Widget head(String x)=>Padding(padding:const EdgeInsets.all(16),child:Text(x,style:const TextStyle(fontSize:24,fontWeight:FontWeight.bold)));
void inspect(Map<String,String> a){answers={};signed=false;notes='';Navigator.push(context,MaterialPageRoute(builder:(ctx)=>StatefulBuilder(builder:(ctx,up)=>Scaffold(appBar:AppBar(title:const Text('New inspection')),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('SAMPLE CHECKLIST - DEMONSTRATION ONLY',style:TextStyle(color:Colors.red,fontWeight:FontWeight.bold)),head(a['name']!),TextField(decoration:const InputDecoration(labelText:'Technician'),controller:TextEditingController(text:technician),onChanged:(v)=>technician=v),...questions.map((q)=>Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(q),Wrap(spacing:8,children:['Pass','Fail','N/A'].map((v)=>ChoiceChip(label:Text(v),selected:answers[q]==v,onSelected:(_)=>up(()=>answers[q]=v))).toList())])))),TextField(decoration:const InputDecoration(labelText:'Notes'),onChanged:(v)=>notes=v),CheckboxListTile(value:signed,title:const Text('Technician acknowledgement (demo)'),onChanged:(v)=>up(()=>signed=v??false)),FilledButton(onPressed:()async{if(answers.length<questions.length||!signed||technician.trim().isEmpty){ScaffoldMessenger.of(ctx).showSnackBar(const SnackBar(content:Text('Complete all questions and acknowledgement')));return;}final id=DateTime.now().millisecondsSinceEpoch.toString(),result=answers.containsValue('Fail')?'Defects found':'Pass';setState((){inspections.add({'id':id,'asset':a['name'],'assetId':a['id'],'site':a['site'],'technician':technician,'date':DateTime.now().toString().substring(0,10),'result':result,'answers':Map.of(answers),'notes':notes});for(final e in answers.entries.where((e)=>e.value=='Fail')){defects.add({'title':e.key,'assetId':a['id'],'status':'Open'});}});await save();if(ctx.mounted)Navigator.pop(ctx);},child:const Text('Save inspection')),const SizedBox(height:36)])))));}
void detail(Map<String,String> a)=>Navigator.push(context,MaterialPageRoute(builder:(ctx)=>Scaffold(appBar:AppBar(title:Text(a['id']!)),body:ListView(padding:const EdgeInsets.all(16),children:[head(a['name']!),Text(a['site']!),const SizedBox(height:18),Center(child:QrImageView(data:a['id']!,size:190)),const Center(child:Text('Unique equipment QR identifier')),const SizedBox(height:15),FilledButton(onPressed:()=>inspect(a),child:const Text('Start inspection')),head('Service history'),...inspections.where((r)=>r['assetId']==a['id']).map((r)=>ListTile(title:Text(r['date'].toString()+' • '+r['result'].toString()),trailing:IconButton(onPressed:()=>pdf(r),icon:const Icon(Icons.picture_as_pdf)))),if(!inspections.any((r)=>r['assetId']==a['id']))const Text('No inspections yet')]))));
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('FIRE RISK SYSTEMS'),actions:[const Padding(padding:EdgeInsets.only(right:14),child:Center(child:Text('DEMO')))]),body:tab==0?ListView(children:[head('Inspection dashboard'),const Padding(padding:EdgeInsets.all(16),child:Text('OFFLINE DEMO • Sample data, not for live compliance use',style:TextStyle(color:Colors.red))),ListTile(leading:const Icon(Icons.fire_extinguisher),title:Text('Assets: '+assets.length.toString())),ListTile(leading:const Icon(Icons.assignment),title:Text('Inspections: '+inspections.length.toString())),ListTile(leading:const Icon(Icons.warning),title:Text('Defects: '+defects.where((d)=>d['status']!='Closed').length.toString())),FilledButton(onPressed:()=>setState(()=>tab=1),child:const Text('View equipment'))]):tab==1?ListView(children:[head('Fire equipment'),...assets.map((a)=>Card(child:ListTile(leading:const Icon(Icons.qr_code),title:Text(a['name']!),subtitle:Text(a['id']!+' • '+a['site']!),trailing:const Icon(Icons.chevron_right),onTap:()=>detail(a))))]):tab==2?ListView(children:[head('Corrective actions'),if(defects.isEmpty)const ListTile(title:Text('No defects reported')), ...defects.map((d)=>ListTile(title:Text(d['title'].toString()),subtitle:Text(d['assetId'].toString()),trailing:DropdownButton<String>(value:d['status'] as String,items:['Open','In progress','Resolved','Closed'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)async{setState(()=>d['status']=v);await save();}))) ]):ListView(children:[head('Service reports'),if(inspections.isEmpty)const ListTile(title:Text('No service reports yet')), ...inspections.reversed.map((r)=>ListTile(title:Text(r['asset'].toString()),subtitle:Text(r['date'].toString()+' • '+r['result'].toString()),trailing:IconButton(icon:const Icon(Icons.picture_as_pdf),onPressed:()=>pdf(r))))]),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const[NavigationDestination(icon:Icon(Icons.dashboard),label:'Home'),NavigationDestination(icon:Icon(Icons.qr_code),label:'Assets'),NavigationDestination(icon:Icon(Icons.warning),label:'Defects'),NavigationDestination(icon:Icon(Icons.description),label:'Reports')]));}
